### Result
{"checks":[["left radius loaded",true],["isolation",true],["side reset",true],["muscle search/card",true],["muscle isolation",true]]}
### Ran Playwright code
```js
await (async(page)=>{const checks=[];page.setDefaultTimeout(10000);await page.setViewportSize({width:1280,height:820});await page.evaluate(()=>__atlas.goTo('radius_left'));await page.waitForFunction(()=>__atlas.state.sel==='radius_left',{timeout:20000});checks.push(['left radius loaded',await page.locator('#bIso').count()===1]);await page.locator('#bIso').click();checks.push(['isolation',await page.evaluate(()=>__atlas.state.isolate==='radius_left')]);await page.locator('[data-side-view="right"]').click();checks.push(['side reset',await page.evaluate(()=>__atlas.state.sides.arm==='right'&&!__atlas.state.isolate)]);await page.locator('#bList').click();await page.locator('#q').fill('biceps brachii');await page.locator('#dlist [data-id="biceps_brachii"]').first().click();checks.push(['muscle search/card',await page.evaluate(()=>__atlas.state.sel==='biceps_brachii')]);await page.locator('#bIso').click();checks.push(['muscle isolation',await page.evaluate(()=>__atlas.state.isolate==='biceps_brachii')]);return {checks};})(page);
